// Fixture paths. Media fixtures are generated by scripts/gen-fixtures.mjs (WS1) and committed.
// sample.srt and sample.vtt are hand-written text fixtures committed with the tests.
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const FIXTURES = {
  h264: 'h264-aac-640x360-5s.mp4',
  vp9: 'vp9-opus-640x360-5s.webm',
  h264NoAudio: 'h264-1280x720-3s-noaudio.mp4',
  mov: 'h264-aac-3s.mov',
  vertical: 'h264-aac-360x640-3s.mp4',
  hd1080: 'h264-aac-1920x1080-4s.mp4',
  speechWav: 'speech-en.wav',
  speechMp4: 'speech-en.mp4',
  toneMp3: 'tone-10s.mp3',
  toneWav: 'tone-10s.wav',
  toneM4a: 'tone-10s.m4a',
  toneOgg: 'tone-10s.ogg',
  srt: 'sample.srt',
  vtt: 'sample.vtt',
  corrupt: 'corrupt.mp4',
  notMedia: 'not-media.mp4',
} as const;

/** The fixed script spoken in speech-en.wav / speech-en.mp4. */
export const SPEECH_SCRIPT =
  'Hello and welcome to Framelab. Everything here runs in your browser. Your files never leave your device.';

export function fixturePath(name: string): string {
  return fileURLToPath(new URL(`../fixtures/${name}`, import.meta.url));
}

/** Absolute path of a fixture; throws a clear error when it has not been generated yet. */
export function fixture(name: string): string {
  const p = fixturePath(name);
  if (!existsSync(p)) {
    throw new Error(`fixture ${name} is missing: run "node scripts/gen-fixtures.mjs" (WS1)`);
  }
  return p;
}
